-- ============================================================
-- starwarsunlimited — схема таблиц
-- Сгенерировано автоматически из docs/dbml/schema.dbml
-- Команда: dotnet run --project tools/DbmlToSql
-- ============================================================

BEGIN;

-- sets
-- Сет (издание) карт: SOR, SHD, JTL, ...
CREATE TABLE IF NOT EXISTS "sets" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(120) NOT NULL,
  "code" varchar(20) NOT NULL UNIQUE,
  "description" text,
  "release_date" date,
  "sort_value" integer NOT NULL DEFAULT 0
);

-- rarities
-- Редкость карты: Common, Uncommon, Rare, Legendary, Special
CREATE TABLE IF NOT EXISTS "rarities" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(60) NOT NULL UNIQUE,
  "character" varchar(10) NOT NULL,
  "color" varchar(10),
  "sort_value" integer NOT NULL DEFAULT 0
);

-- card_types
-- Тип карты: Leader, Unit, Event, Base, Upgrade, Token
CREATE TABLE IF NOT EXISTS "card_types" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(60) NOT NULL UNIQUE,
  "value" varchar(60) NOT NULL,
  "sort_value" integer NOT NULL DEFAULT 0
);

-- aspects
-- Аспект (цвет) карты: Vigilance, Villainy, Cunning, Heroism, Aggression, Command
CREATE TABLE IF NOT EXISTS "aspects" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(60) NOT NULL UNIQUE,
  "color" varchar(10),
  "description" text,
  "sort_value" integer NOT NULL DEFAULT 0
);

-- traits
-- Трейт (способность/признак) карты: Droid, Sith, Vehicle, ...
CREATE TABLE IF NOT EXISTS "traits" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(60) NOT NULL UNIQUE,
  "description" text
);

-- cards
-- Основная сущность: карточка
CREATE TABLE IF NOT EXISTS "cards" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "external_id" integer NOT NULL UNIQUE,
    -- Идентификатор карты в API starwarsunlimited.com
  "title" varchar(150) NOT NULL,
  "subtitle" varchar(150),
  "card_number" integer NOT NULL,
    -- Номер карты внутри сета
  "card_count" integer,
    -- Количество карт в сете
  "cost" integer,
  "hp" integer,
  "power" integer,
  "text" text,
    -- Текст способности карты
  "artist" varchar(120),
  "serial_code" varchar(40) NOT NULL,
    -- Серийный номер, например 0101005 или IC27010001
  "art_url" text,
    -- Ссылка на изображение карты
  "is_unique" boolean NOT NULL DEFAULT false,
  "is_foil" boolean NOT NULL DEFAULT false,
  "is_hyperspace" boolean NOT NULL DEFAULT false,
  "set_id" integer NOT NULL,
  "rarity_id" integer NOT NULL,
  "type_id" integer NOT NULL,
  "created_at" timestamp,
  "updated_at" timestamp
);

-- card_aspects
-- Связь карт и аспектов (многие ко многим)
CREATE TABLE IF NOT EXISTS "card_aspects" (
  "card_id" integer NOT NULL,
  "aspect_id" integer NOT NULL,
  PRIMARY KEY ("card_id", "aspect_id")
);

-- card_traits
-- Связь карт и трейтов (многие ко многим)
CREATE TABLE IF NOT EXISTS "card_traits" (
  "card_id" integer NOT NULL,
  "trait_id" integer NOT NULL,
  PRIMARY KEY ("card_id", "trait_id")
);

-- admins
-- Администратор сайта
CREATE TABLE IF NOT EXISTS "admins" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "username" varchar(60) NOT NULL UNIQUE,
  "email" varchar(150) NOT NULL UNIQUE,
  "password_hash" varchar(200) NOT NULL,
    -- PBKDF2-SHA256, base64
  "password_salt" varchar(100) NOT NULL,
    -- Соль PBKDF2, base64
  "role" varchar(30) NOT NULL DEFAULT 'admin',
  "created_at" timestamp,
  "last_login_at" timestamp
);

-- comments
-- Комментарий пользователя к карточке
CREATE TABLE IF NOT EXISTS "comments" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "card_id" integer NOT NULL,
  "author" varchar(80) NOT NULL,
  "body" text NOT NULL,
  "created_at" timestamp
);

COMMIT;
